/**
 * Excel export, against the workbooks DevExpress 20.1 exported for the same
 * reports and data (`RepxProbe render`, 2026-10-30, row 19 of
 * docs/proposals/devexpress-parity.md). Each expectation is DevExpress's file
 * read into a grid -- column widths, row heights, merged ranges, links, and
 * every cell's type, value, number format, font and alignment -- and Forma's
 * file is read back the same way. c05's grid is large, so it is compared by a
 * fingerprint of that same form, with spot checks.
 */
import { describe, it, expect } from 'vitest';
import { inflateRawSync } from 'node:zlib';
import { createHash } from 'node:crypto';
import { excelFormat, reportToXlsx } from './xlsxExport';
import { parseReportStructure } from './reportPreview';

/** The parts of a zip, by name. */
function unzip(bytes: Uint8Array): Record<string, string> {
  const buf = Buffer.from(bytes);
  let eocd = buf.length - 22;
  while (eocd >= 0 && buf.readUInt32LE(eocd) !== 0x06054b50) eocd--;
  let p = buf.readUInt32LE(eocd + 16);
  const parts: Record<string, string> = {};
  for (let i = 0; i < buf.readUInt16LE(eocd + 10); i++) {
    const method = buf.readUInt16LE(p + 10);
    const size = buf.readUInt32LE(p + 20);
    const nameLen = buf.readUInt16LE(p + 28);
    const local = buf.readUInt32LE(p + 42);
    const name = buf.subarray(p + 46, p + 46 + nameLen).toString('utf8');
    const start = local + 30 + buf.readUInt16LE(local + 26) + buf.readUInt16LE(local + 28);
    const body = buf.subarray(start, start + size);
    parts[name] = (method === 8 ? inflateRawSync(body) : body).toString('utf8');
    p += 46 + nameLen + buf.readUInt16LE(p + 30) + buf.readUInt16LE(p + 32);
  }
  return parts;
}

const attr = (s: string, n: string) => new RegExp(`\\s${n}="([^"]*)"`).exec(s)?.[1] ?? null;
const unescape = (s: string) => s.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

/** A workbook in the comparable form the expectations were written in. */
function canonical(bytes: Uint8Array): string {
  const parts = unzip(bytes);
  const sheet = parts['xl/worksheets/sheet1.xml'];
  const styles = parts['xl/styles.xml'];
  const strings = [...(parts['xl/sharedStrings.xml'] ?? '').matchAll(/<si>([\s\S]*?)<\/si>/g)]
    .map((m) => unescape([...m[1].matchAll(/<t[^>]*>([\s\S]*?)<\/t>/g)].map((t) => t[1]).join('')));
  const numFmts = Object.fromEntries([...styles.matchAll(/<numFmt\b([^>]*)\/>/g)].map((m) => [attr(m[1], 'numFmtId'), unescape(attr(m[1], 'formatCode') ?? '')]));
  const fonts = [...(/<fonts[^>]*>([\s\S]*?)<\/fonts>/.exec(styles)?.[1] ?? '').matchAll(/<font>([\s\S]*?)<\/font>/g)].map((m) => ({
    bold: /<b\s*\/>/.test(m[1]), size: Number(attr(/<sz[^>]*>/.exec(m[1])?.[0] ?? '', 'val')), name: attr(/<name[^>]*>/.exec(m[1])?.[0] ?? '', 'val'),
  }));
  const xfs = [...(/<cellXfs[^>]*>([\s\S]*?)<\/cellXfs>/.exec(styles)?.[1] ?? '').matchAll(/<xf\b([^>]*?)(?:\/>|>([\s\S]*?)<\/xf>)/g)].map((m) => {
    const id = attr(m[1], 'numFmtId') ?? '0';
    const align = /<alignment\b([^>]*)\/>/.exec(m[2] ?? '');
    const builtin: Record<string, string> = { '0': 'General', '49': '@' };
    return { fmt: builtin[id] ?? numFmts[id] ?? `builtin:${id}`, font: fonts[Number(attr(m[1], 'fontId'))], h: align ? attr(align[1], 'horizontal') : null, v: align ? attr(align[1], 'vertical') : null };
  });
  const cells: (string | number | boolean | null | undefined)[][] = [];
  for (const row of sheet.matchAll(/<row\b([^>]*?)(?:\/>|>([\s\S]*?)<\/row>)/g)) {
    for (const c of (row[2] ?? '').matchAll(/<c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g)) {
      const v = /<v>([\s\S]*?)<\/v>/.exec(c[2] ?? '')?.[1];
      if (v === undefined) continue;
      const type = attr(c[1], 't') === 's' ? 's' : 'n';
      const xf = xfs[Number(attr(c[1], 's') ?? 0)];
      cells.push([attr(c[1], 'r'), type, type === 's' ? strings[Number(v)] : Number(Number(v).toPrecision(12)), xf.fmt, xf.font?.bold ?? false, xf.font?.size, xf.font?.name, xf.h, xf.v]);
    }
  }
  cells.sort((a, b) => String(a[0]).localeCompare(String(b[0])));
  return JSON.stringify({
    cols: [...sheet.matchAll(/<col\b([^>]*)\/>/g)].map((m) => Number(attr(m[1], 'width'))),
    rows: [...sheet.matchAll(/<row\b([^>]*?)(?:\/>|>)/g)].map((m) => Number(attr(m[1], 'ht'))),
    merges: [...sheet.matchAll(/<mergeCell\b([^>]*)\/>/g)].map((m) => attr(m[1], 'ref')).sort(),
    links: [...sheet.matchAll(/<hyperlink\b([^>]*)\/>/g)].length,
    cells,
  });
}

