describe('reportToXlsx, as DevExpress exports a workbook', () => {
  it('writes c04 cell for cell: currency as numbers, a merge for every wide control', () => {
    expect(canonical(reportToXlsx(parseReportStructure(C04), C04_ROWS.length, { rows: C04_ROWS }))).toBe(C04_GRID);
  });

  it('writes c05 cell for cell: groups, dates as serials, a prefix in every section', () => {
    const grid = canonical(reportToXlsx(parseReportStructure(C05), C05_ROWS.length, { rows: C05_ROWS }));
    const cells = new Map((JSON.parse(grid).cells as unknown[][]).map((c) => [c[0], c]));
    expect(cells.get('A3')).toEqual(['A3', 's', 'North', '"Region: "@', true, 11, 'Arial', 'left', 'top']);
    expect(cells.get('B5')).toEqual(['B5', 'n', 46191, 'dd\\ MMM\\ yyyy', false, 9, 'Arial', 'left', 'top']);
    expect(cells.get('J7')?.[2]).toBe(1001.07);
    expect(createHash('sha256').update(grid).digest('hex')).toBe(C05_GRID_SHA256);
  });

  it('writes c06 cell for cell, each order followed by its own lines', () => {
    const related = (_: string, master: Record<string, string>) => C06_LINES.filter((l) => l.OrderID === master.OrderID);
    expect(canonical(reportToXlsx(parseReportStructure(C06), C06_ORDERS.length, { rows: C06_ORDERS, related }))).toBe(C06_GRID);
  });

  it('keeps every link, as DevExpress did for c08', () => {
    expect(canonical(reportToXlsx(parseReportStructure(C08), C08_ROWS.length, { rows: C08_ROWS }))).toBe(C08_GRID);
    const parts = unzip(reportToXlsx(parseReportStructure(C08), C08_ROWS.length, { rows: C08_ROWS }));
    expect(parts['xl/worksheets/_rels/sheet1.xml.rels']).toContain('Target="https://example.com/customers/C0001" TargetMode="External"');
  });
});

describe('excelFormat', () => {
  it('converts the format strings DevExpress converted', () => {
    expect(excelFormat('{0:c2}', 'number')).toBe('[$$-0409]#,##0.00;([$$-0409]#,##0.00);[$$-0409]#,##0.00;@');
    expect(excelFormat('Total {0:c2}', 'number')).toBe('"Total "[$$-0409]#,##0.00;"Total "([$$-0409]#,##0.00);"Total "[$$-0409]#,##0.00;"Total "@');
    expect(excelFormat('{0:n0}', 'number')).toBe('#,##0');
    expect(excelFormat('{0} orders', 'number')).toBe('@" orders"');
    expect(excelFormat('Region: {0}', 'text')).toBe('"Region: "@');
    expect(excelFormat('{0:dd MMM yyyy}', 'date')).toBe('dd\\ MMM\\ yyyy');
    expect(excelFormat('{0:yyyy-MM-dd}', 'date')).toBe('yyyy-MM-dd');
  });

  it('falls back to General, or text, when there is no format', () => {
    expect(excelFormat(null, 'number')).toBe('General');
    expect(excelFormat(null, 'text')).toBe('@');
    expect(excelFormat('{0:0.00;(0.00)}', 'number')).toBe('0.00;(0.00)');
  });
});

