  const S26_GRID = "{\"cols\":[6.86,27.43],\"rows\":[14.25,18],\"merges\":[],\"links\":0,\"cells\":[[\"B2\",\"s\",\"AWAY FROM THE EDGES\",\"General\",false,9,\"Times New Roman\",\"left\",\"top\"]]}";

